<script setup>


import {computed, inject, onBeforeUnmount, ref} from 'vue'


import {toast} from '../../shared/composables/toast.js'
const props=defineProps({model:Object,item:Object,disabled:Boolean}),emit=defineEmits(['update:modelValue']),api=inject('api')
const open=ref(false),query=ref(''),source=ref(props.item?.source?.replace(/^zentao:/,'')||'manual'),sources=ref([]),mode=ref('default'),items=ref([]),busy=ref(false),error=ref(''),page=ref(1),cursor=ref(''),hasMore=ref(false),picked=ref('')
let sequence=0
const ownership=computed(()=>props.model.delivery_ownership||{mode:'self',work_item_id:props.item?.id,origin_work_item_id:props.item?.id})
function setMode(value){props.model.delivery_ownership={mode:value,origin_work_item_id:props.item.id,work_item_id:value==='self'?props.item.id:0};picked.value='';if(value==='follow'){open.value=true;load(true)}}
async function load(reset=false){const generation=++sequence;busy.value=true;error.value='';items.value=[];if(reset){page.value=1;cursor.value=''}try{if(!sources.value.length)sources.value=await api('api/research/work-items/sources');const params=new URLSearchParams({connection:source.value,product:'0',q:query.value,page:String(page.value),page_size:'20',cursor:cursor.value,status:mode.value==='active'?'active':'',main_candidate:mode.value==='default'?'1':'',relation:mode.value==='participating'?'participating':''});const data=await api('api/research/work-items/page?'+params);if(generation!==sequence)return;items.value=data.items.filter(w=>w.id!==props.item.id);cursor.value=data.next_cursor||'';hasMore.value=data.has_more;page.value=data.page}catch(e){if(generation===sequence){error.value=e.message;toast(e.message,'error')}}finally{if(generation===sequence)busy.value=false}}
async function select(w){if(busy.value)return;busy.value=true;try{const target=w.id?w:await api('api/research/work-items/attach',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({connection:w.source.slice(7),external_id:w.external_id})});props.model.delivery_ownership={mode:'follow',origin_work_item_id:props.item.id,work_item_id:target.id};picked.value=(target.external_id||'#'+target.id)+' · '+target.title;open.value=false}catch(e){toast(e.message,'error')}finally{busy.value=false}}
onBeforeUnmount(()=>sequence++)

import OptionPicker from '../../shared/components/OptionPicker.vue'



import {Accordion,AccordionContent,AccordionItem,AccordionTrigger,Button,Field,FieldLabel,Input,Spinner} from '../../shared/shadcn-ui.js'

import {InputGroup,InputGroupInput,InputGroupAddon,InputGroupButton} from '../../shared/shadcn-ui.js'

import {XIcon} from '@lucide/vue'
</script>
<template><div class="delivery-ownership"><div class="ownership-row"><Field ><FieldLabel as="div">生产交付归属</FieldLabel><OptionPicker :model-value="ownership.mode" :options="[{value:'self',label:'由当前工作项交付'},{value:'follow',label:'随其他工作项交付'},{value:'draft',label:'先保存草稿（开发／测试）'}]" :disabled="disabled||busy" :style="{width:'240px',maxWidth:'100%'}" @update:model-value="setMode"/></Field><template v-if="ownership.mode==='follow'"><span>{{picked||'主工作项 #'+(ownership.work_item_id||'待选择')}}</span></template></div><small v-if="ownership.mode==='draft'">开发／测试可以继续；生产前需关联主项，或在版本中明确选入本条变更。</small><small v-else-if="ownership.mode==='follow'">保留当前 Bug 作为来源；仅此条变更随主项交付，不建立禅道父子关系。</small><Accordion v-if="ownership.mode==='follow'" class="platform-collapse" type="multiple" :model-value="(open?['owner']:[]||[]).map(String)" @update:model-value="(keys=>{open=keys.length>0;if(open)load(true)})($event)"><AccordionItem :disabled="disabled||busy" :value="String(&quot;owner&quot;)"><AccordionTrigger>详细设置</AccordionTrigger><AccordionContent force-mount v-show="!(!(open?['owner']:[]||[]).map(String).includes(String(&quot;owner&quot;)))"><div class="ownership-picker"><div class="ownership-row"><InputGroup  class="min-w-0 "><InputGroupInput v-model="query" placeholder="搜索主工作项标题或编号" @keyup.enter="load(true)"/><InputGroupAddon align="inline-end"><InputGroupButton v-if="query" :disabled="false" size="icon-xs" aria-label="清空输入" @click="query='' "><XIcon/></InputGroupButton></InputGroupAddon></InputGroup><OptionPicker v-model="source" :options="[...sources.map(s=>({value:s.name,label:s.name})),{value:'manual',label:'自定义工作项'}]" :style="{width:'170px',maxWidth:'100%'}" @change="load(true)"/><OptionPicker v-model="mode" :options="[{value:'default',label:'进行中及未上线'},{value:'active',label:'只看进行中'},{value:'participating',label:'我参与的'},{value:'all',label:'全部状态'}]" :style="{width:'170px',maxWidth:'100%'}" @change="load(true)"/><Button @click="load(true)" variant="outline" size="default" type="button" :disabled="(busy)"><Spinner v-if="busy"/>搜索</Button></div><div :aria-busy="busy" class="owner-results"><Button v-for="w in items" :key="w.source+':'+(w.external_id||w.id)" @click="select(w)" variant="outline" size="default" type="button" :disabled="(busy)"><span>{{w.external_id||'#'+w.id}} · {{w.title}}</span><small>{{({active:'进行中',resolved:'已解决',closed:'已关闭'})[w.external_status]||w.status}}</small></Button><p v-if="!items.length">{{busy?'正在查询…':error||'没有匹配项，可切换全部状态或搜索编号。'}}</p></div><div class="ownership-row"><Button @click="page++;load()" variant="outline" size="default" type="button" :disabled="(busy||!hasMore)">下一页</Button><Button @click="open=false" variant="outline" size="default" type="button" :disabled="(busy)">收起选择</Button></div></div></AccordionContent></AccordionItem></Accordion></div></template>
<style scoped>.delivery-ownership{grid-column:1/-1;display:grid;gap:8px;padding-top:12px;border-top:1px solid var(--border)}.ownership-row{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.ownership-row label{display:flex;align-items:center;gap:10px}.delivery-ownership small{color:var(--muted-foreground)}.ownership-picker{padding:12px;border:1px solid var(--border);border-radius:var(--radius);display:grid;gap:10px}.owner-results{max-height:220px;overflow:auto}.owner-results small{flex-shrink:0}</style>
